stokes-law-terminal-settling-velocity-pa.js:
(() => {
  'use strict';
  const dpEl = document.getElementById('st-dp'), rhopEl = document.getElementById('st-rhop');
  const rhofEl = document.getElementById('st-rhof'), muEl = document.getElementById('st-mu');
  const vtResEl = document.getElementById('st-res-vt'), repResEl = document.getElementById('st-res-rep');

  const g = 9.80665; // m/s^2

  function update() {
    const dp_um = parseFloat(dpEl.value), rho_p = parseFloat(rhopEl.value);
    const rho_f = parseFloat(rhofEl.value), mu_cP = parseFloat(muEl.value);

    if (isNaN(dp_um) || isNaN(rho_p) || isNaN(rho_f) || isNaN(mu_cP) || dp_um <= 0 || rho_p <= rho_f || mu_cP <= 0) return;

    const dp_m = dp_um * 1e-6;
    const r_m = dp_m / 2.0;
    const mu_Pa_s = mu_cP * 1e-3;

    // Stokes' Law terminal velocity: v_t = ( 2 * r^2 * (rho_p - rho_f) * g ) / ( 9 * mu )  [m / s]
    const v_t_m_s = (2.0 * Math.pow(r_m, 2) * (rho_p - rho_f) * g) / (9.0 * mu_Pa_s);
    const v_t_mm_s = v_t_m_s * 1000.0;
    const v_t_m_hr = v_t_m_s * 3600.0;

    // Particle Reynolds number: Re_p = ( rho_f * v_t * dp ) / mu
    const Re_p = (rho_f * v_t_m_s * dp_m) / mu_Pa_s;

    let valid = '', color = '#22543d';
    if (Re_p < 0.2) {
      valid = 'CREEPING FLOW (Re_p < 0.2: Stokes law strictly valid ✓)';
      color = '#22543d';
    } else if (Re_p <= 1.0) {
      valid = 'TRANSITION REGIME (Re_p 0.2 - 1.0: Minor inertial drag deviation)';
      color = '#ea580c';
    } else {
      valid = 'TURBULENT WAKE (Re_p > 1.0: Stokes law overestimates settling velocity)';
      color = '#c53030';
    }

    vtResEl.textContent = 'Settling Velocity v_t = ' + v_t_mm_s.toFixed(2) + ' mm/s (' + v_t_m_hr.toFixed(2) + ' m/hr)';
    repResEl.textContent = 'Particle Re_p = ' + Re_p.toFixed(3) + ' (' + valid + ')';
    repResEl.style.color = color;
  }

  [dpEl, rhopEl, rhofEl, muEl].forEach(el => el.addEventListener('input', update));
  update();
})();

stream-discharge-manning-open-channel-fl.js:
(() => {
  'use strict';
  const bEl = document.getElementById('mn-b'), yEl = document.getElementById('mn-y');
  const sEl = document.getElementById('mn-s'), nEl = document.getElementById('mn-n');
  const qResEl = document.getElementById('mn-res-q'), vResEl = document.getElementById('mn-res-v');

  function update() {
    const b = parseFloat(bEl.value), y = parseFloat(yEl.value);
    const S = parseFloat(sEl.value), n = parseFloat(nEl.value);

    if (isNaN(b) || isNaN(y) || isNaN(S) || isNaN(n) || b <= 0 || y <= 0 || S <= 0 || n <= 0) return;

    // Cross-sectional Area A = b * y
    const Area = b * y;
    // Wetted perimeter P_wet = b + 2*y
    const P_wet = b + (2.0 * y);
    // Hydraulic radius R_h = A / P_wet
    const R_h = Area / P_wet;

    // Manning's equation for velocity: v = (1 / n) * R_h^(2/3) * S^(1/2)  [m/s]
    const v = (1.0 / n) * Math.pow(R_h, 2.0 / 3.0) * Math.sqrt(S);
    // Discharge Q = A * v  [m^3 / s]
    const Q = Area * v;

    qResEl.textContent = 'Discharge Q = ' + Q.toFixed(2) + ' m³ / s';
    vResEl.textContent = 'Velocity v = ' + v.toFixed(2) + ' m/s | R_h = ' + R_h.toFixed(3) + ' m (A = ' + Area.toFixed(2) + ' m², P_wet = ' + P_wet.toFixed(2) + ' m @ n = ' + n + ')';
  }

  [bEl, yEl, sEl, nEl].forEach(el => el.addEventListener('input', update));
  update();
})();

streeter-phelps-dissolved-oxygen-sag-cur.js:
(() => {
  'use strict';
  const kdEl = document.getElementById('sp-kd'), krEl = document.getElementById('sp-kr');
  const l0El = document.getElementById('sp-l0'), d0El = document.getElementById('sp-d0'), satEl = document.getElementById('sp-dosat');
  const minResEl = document.getElementById('sp-res-min'), tcResEl = document.getElementById('sp-res-tc');

  function update() {
    const k_d = parseFloat(kdEl.value), k_r = parseFloat(krEl.value);
    const L_0 = parseFloat(l0El.value), D_0 = parseFloat(d0El.value), DO_sat = parseFloat(satEl.value);

    if (isNaN(k_d) || isNaN(k_r) || isNaN(L_0) || isNaN(D_0) || isNaN(DO_sat) || k_d <= 0 || k_r <= 0 || k_d === k_r || L_0 <= 0 || D_0 < 0 || DO_sat <= 0) return;

    // Self-purification constant f = k_r / k_d
    const f = k_r / k_d;

    // Critical time t_c:
    // t_c = ( 1 / (k_r - k_d) ) * ln( (k_r / k_d) * [ 1 - (D_0 * (k_r - k_d) / (k_d * L_0)) ] )
    const bracket = 1.0 - ( (D_0 * (k_r - k_d)) / (k_d * L_0) );
    if (bracket <= 0) return;

    const t_c = (1.0 / (k_r - k_d)) * Math.log(f * bracket);

    // Critical oxygen deficit D_c = (k_d / k_r) * L_0 * exp(-k_d * t_c)
    // Streeter-Phelps equation: D(t) = ( (k_d * L_0) / (k_r - k_d) ) * ( exp(-k_d*t) - exp(-k_r*t) ) + D_0 * exp(-k_r*t)
    const D_c = ((k_d * L_0) / (k_r - k_d)) * (Math.exp(-k_d * t_c) - Math.exp(-k_r * t_c)) + (D_0 * Math.exp(-k_r * t_c));

    const DO_min = Math.max(0.0, DO_sat - D_c);

    let qual = '', color = '#22543d';
    if (DO_min >= 5.0) { qual = 'HEALTHY AQUATIC LIFE (DO ≥ 5.0 mg/L ✓)'; color = '#22543d'; }
    else if (DO_min >= 2.0) { qual = 'STRESSED FISHERY (2.0 ≤ DO < 5.0 mg/L: Sensitive fish die-off risk)'; color = '#ea580c'; }
    else { qual = 'SEPTIC / ANOXIC CONDITIONS (DO < 2.0 mg/L: Severe fish kills ✗)'; color = '#c53030'; }

    minResEl.textContent = 'Minimum DO = ' + DO_min.toFixed(2) + ' mg/L (' + qual.split(' (')[0] + ')';
    minResEl.style.color = color;
    tcResEl.textContent = 'Critical Sag t_c = ' + t_c.toFixed(2) + ' Days (Max Deficit D_c = ' + D_c.toFixed(2) + ' mg/L | Self-Purification f = ' + f.toFixed(2) + ')';
  }

  [kdEl, krEl, l0El, d0El, satEl].forEach(el => el.addEventListener('input', update));
  update();
})();

(() => {
  'use strict';
  const l0El = document.getElementById('sp-l0'), d0El = document.getElementById('sp-d0');
  const k1El = document.getElementById('sp-k1'), k2El = document.getElementById('sp-k2');
  const dcResEl = document.getElementById('sp-res-dc'), tcResEl = document.getElementById('sp-res-tc');

  const DO_sat_20C = 9.10; // mg / L saturation at 20°C

  function update() {
    const L0 = parseFloat(l0El.value), D0 = parseFloat(d0El.value);
    const k1 = parseFloat(k1El.value), k2 = parseFloat(k2El.value);

    if (isNaN(L0) || isNaN(D0) || isNaN(k1) || isNaN(k2) || L0 <= 0 || k1 <= 0 || k2 <= 0 || k1 === k2) return;

    // Critical time formula: t_c = ( 1 / (k2 - k1) ) * ln( (k2 / k1) * ( 1 - D0*(k2 - k1)/(k1*L0) ) )
    const term = (k2 / k1) * (1.0 - (D0 * (k2 - k1)) / (k1 * L0));
    if (term <= 0) return;

    const t_c = (1.0 / (k2 - k1)) * Math.log(term);

    // Streeter-Phelps DO deficit at t_c:
    // D(t) = [ (k1 * L0) / (k2 - k1) ] * ( exp(-k1 * t) - exp(-k2 * t) ) + D0 * exp(-k2 * t)
    const D_c = ((k1 * L0) / (k2 - k1)) * (Math.exp(-k1 * t_c) - Math.exp(-k2 * t_c)) + (D0 * Math.exp(-k2 * t_c));
    const minDO = Math.max(0, DO_sat_20C - D_c);

    let status = '', color = '#22543d';
    if (minDO >= 5.0) { status = 'HEALTHY AQUATIC ECOSYSTEM (Min DO ≥ 5.0 mg/L: Supports game fish)'; color = '#22543d'; }
    else if (minDO >= 2.0) { status = 'STRESSED FISH HABITAT (Min DO 2.0 - 5.0 mg/L: Sensitive fish flee / die)'; color = '#ea580c'; }
    else { status = 'SEVERE ANOXIA / FISH KILL (Min DO < 2.0 mg/L: Anaerobic odors / massive mortality!)'; color = '#c53030'; }

    dcResEl.textContent = 'Critical DO Deficit D_c = ' + D_c.toFixed(2) + ' mg / L (' + status.split(' (')[0] + ')';
    dcResEl.style.color = color;
    tcResEl.textContent = 'Critical Sag t_c = ' + t_c.toFixed(2) + ' Days | Min DO = ' + minDO.toFixed(2) + ' mg/L (Saturation: 9.10 mg/L @ 20°C, k₁=' + k1 + ', k₂=' + k2 + ')';
    tcResEl.style.color = color;
  }

  [l0El, d0El, k1El, k2El].forEach(el => el.addEventListener('input', update));
  update();
})();

stribeck-curve-lubrication-regime-hersey.js:
(() => {
  'use strict';
  const muEl = document.getElementById('str-mu'), nEl = document.getElementById('str-n'), pEl = document.getElementById('str-p');
  const hResEl = document.getElementById('str-res-h'), regResEl = document.getElementById('str-res-reg');

  function update() {
    const mu = parseFloat(muEl.value), N = parseFloat(nEl.value), P = parseFloat(pEl.value);
    if (isNaN(mu) || isNaN(N) || isNaN(P) || mu <= 0 || N <= 0 || P <= 0) return;

    // Hersey number H = (mu * N) / P where mu in cP (mPa*s), N in RPM, P in MPa
    const H = (mu * N) / P;

    let regime = '';
    let f_coeff = 0.0;
    let color = '#22543d';

    if (H < 100) {
      regime = 'BOUNDARY LUBRICATION (f ≈ 0.10 - 0.15: Direct metal-to-metal asperity contact, high wear!)';
      f_coeff = 0.12;
      color = '#c53030';
    } else if (H < 1500) {
      regime = 'MIXED / ELASTOHYDRODYNAMIC (f ≈ 0.02 - 0.05: Partial fluid support, moderate wear risk)';
      f_coeff = 0.035;
      color = '#d97706';
    } else {
      regime = 'HYDRODYNAMIC FULL-FILM (f ≈ 0.002 - 0.008: Complete fluid wedge separation, zero wear)';
      f_coeff = 0.0015 * Math.pow(H / 1000, 0.5);
      color = '#22543d';
    }

    hResEl.textContent = 'Hersey H = ' + Math.round(H).toLocaleString() + ' (f ≈ ' + f_coeff.toFixed(4) + ')';
    hResEl.style.color = color;
    regResEl.textContent = regime;
    regResEl.style.color = color;
  }

  [muEl, nEl, pEl].forEach(el => el.addEventListener('input', update));
  update();
})();

structural-buckling-euler-effective-leng.js:
(() => {
  'use strict';
  const lEl = document.getElementById('bck-l'), eEl = document.getElementById('bck-e');
  const iEl = document.getElementById('bck-i'), kEl = document.getElementById('bck-k');
  const pResEl = document.getElementById('bck-res-pcr'), efResEl = document.getElementById('bck-res-eff');

  function update() {
    const Lm = parseFloat(lEl.value), EGpa = parseFloat(eEl.value);
    const I_cm4 = parseFloat(iEl.value), K = parseFloat(kEl.value);

    if (isNaN(Lm) || isNaN(EGpa) || isNaN(I_cm4) || isNaN(K) || Lm <= 0 || EGpa <= 0 || I_cm4 <= 0 || K <= 0) return;

    const E_pa = EGpa * 1e9;
    const I_m4 = I_cm4 * 1e-8; // cm^4 to m^4
    const Le_m = K * Lm;

    // Euler buckling load: P_cr = ( pi^2 * E * I ) / Le^2  [Newtons]
    const Pcr_N = (Math.pow(Math.PI, 2) * E_pa * I_m4) / Math.pow(Le_m, 2);
    const Pcr_kN = Pcr_N / 1000;
    const Pcr_kips = Pcr_kN * 0.224809;
    const Pcr_tonnes = Pcr_kN / 9.80665;

    pResEl.textContent = 'P_cr = ' + Math.round(Pcr_kN).toLocaleString() + ' kN (' + Math.round(Pcr_kips).toLocaleString() + ' kips)';
    efResEl.textContent = 'Effective Length L_e = ' + Le_m.toFixed(2) + ' m (K = ' + K + ') | Critical Capacity: ' + Math.round(Pcr_tonnes).toLocaleString() + ' Tonnes';
  }

  [lEl, eEl, iEl].forEach(el => el.addEventListener('input', update));
  kEl.addEventListener('change', update);
  update();
})();

student-scientific-calculator.js:
﻿(function() {
  'use strict';
  var slug = 'student-scientific-calculator';
  var inputEl = document.getElementById(slug + '-input');
  var modeEl = document.getElementById(slug + '-mode');
  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');
  function setMsg(t, e){ msgEl.textContent=t; msgEl.classList.toggle('is-error', !!e); }

  function safeEval(expr, angleMode) {
    var toRad = angleMode === 'deg' ? '(Math.PI/180)*' : '';
    var fromRad = angleMode === 'deg' ? '(180/Math.PI)*' : '';
    var s = expr;
    s = s.replace(/\bPI\b/gi, 'Math.PI');
    s = s.replace(/\bE\b/g, 'Math.E');
    s = s.replace(/\bsin\(/gi, 'Math.sin(' + toRad + '(');
    s = s.replace(/\bcos\(/gi, 'Math.cos(' + toRad + '(');
    s = s.replace(/\btan\(/gi, 'Math.tan(' + toRad + '(');
    s = s.replace(/\basin\(/gi, fromRad + 'Math.asin(');
    s = s.replace(/\bacos\(/gi, fromRad + 'Math.acos(');
    s = s.replace(/\batan\(/gi, fromRad + 'Math.atan(');
    s = s.replace(/\bsqrt\(/gi, 'Math.sqrt(');
    s = s.replace(/\babs\(/gi, 'Math.abs(');
    s = s.replace(/\blog\(/gi, 'Math.log10(');
    s = s.replace(/\bln\(/gi, 'Math.log(');
    s = s.replace(/\bexp\(/gi, 'Math.exp(');
    s = s.replace(/\bpow\(/gi, 'Math.pow(');
    s = s.replace(/\bmin\(/gi, 'Math.min(');
    s = s.replace(/\bmax\(/gi, 'Math.max(');
    s = s.replace(/\^/g, '**');
    if (/[^0-9+\-*/().,%\s]/.test(s.replace(/Math\.\w+/g, ''))) {
      throw new Error('Invalid characters in expression.');
    }
    try {
      var result = new Function('return (' + s + ')')();
      if (typeof result !== 'number' || isNaN(result)) throw new Error('Result is not a valid number.');
      return result;
    } catch(e) {
      throw new Error('Could not evaluate expression. Check syntax.');
    }
  }

  btn.addEventListener('click', function() {
    var expr = inputEl.value.trim();
    if (!expr) { setMsg('Please enter an expression.', true); outputEl.value=''; copyBtn.disabled=true; return; }
    try {
      var result = safeEval(expr, modeEl.value);
      var out = 'Expression: ' + expr + '\n';
      out += 'Angle Mode: ' + (modeEl.value === 'deg' ? 'Degrees' : 'Radians') + '\n\n';
      out += 'Result: ' + result + '\n';
      out += 'Rounded (4 dp): ' + result.toFixed(4);
      outputEl.value = out;
      copyBtn.disabled = false;
      setMsg('Calculation complete.');
    } catch(e) {
      setMsg('Error: ' + e.message, true);
      outputEl.value = '';
      copyBtn.disabled = true;
    }
  });

  inputEl.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') { e.preventDefault(); btn.click(); }
  });

  copyBtn.addEventListener('click', function() { if (window.NikTool && typeof window.NikTool.copy === 'function') { window.NikTool.copy(outputEl.value, copyBtn); } else if (navigator.clipboard) { navigator.clipboard.writeText(outputEl.value); } setMsg('Result copied.'); });
  clearBtn.addEventListener('click', function() { inputEl.value=''; outputEl.value=''; copyBtn.disabled=true; setMsg('Cleared.'); });
})();

