(() => {
  'use strict';
  const cEl = document.getElementById('tz-c'), pEl = document.getElementById('tz-phi');
  const gEl = document.getElementById('tz-gam'), bEl = document.getElementById('tz-b'), dfEl = document.getElementById('tz-df');
  const quResEl = document.getElementById('tz-res-qult'), qaResEl = document.getElementById('tz-res-qall');

  function update() {
    const c = parseFloat(cEl.value), phiDeg = parseFloat(pEl.value);
    const gamma = parseFloat(gEl.value), B = parseFloat(bEl.value), Df = parseFloat(dfEl.value);

    if (isNaN(c) || isNaN(phiDeg) || isNaN(gamma) || isNaN(B) || isNaN(Df) || c < 0 || phiDeg < 0 || phiDeg > 45 || gamma <= 0 || B <= 0 || Df < 0) return;

    const phiRad = (phiDeg * Math.PI) / 180;
    const q_surcharge = gamma * Df;

    let Nq = 1.0, Nc = 5.14, Ngamma = 0.0;
    if (phiDeg > 0) {
      Nq = Math.exp(Math.PI * Math.tan(phiRad)) * Math.pow(Math.tan((Math.PI / 4) + (phiRad / 2)), 2);
      Nc = (Nq - 1) / Math.tan(phiRad);
      Ngamma = 2 * (Nq + 1) * Math.tan(phiRad);
    }

    const q_ult = (c * Nc) + (q_surcharge * Nq) + (0.5 * gamma * B * Ngamma);
    const q_allow = q_ult / 3.0;

    quResEl.textContent = q_ult.toFixed(1) + ' kPa (q_ult)';
    qaResEl.textContent = q_allow.toFixed(1) + ' kPa (FS = 3.0 | N_c=' + Nc.toFixed(1) + ', N_q=' + Nq.toFixed(1) + ', N_γ=' + Ngamma.toFixed(1) + ')';
  }

  [cEl, pEl, gEl, bEl, dfEl].forEach(el => el.addEventListener('input', update));
  update();
})();

(() => {
  'use strict';
  const bEl = document.getElementById('tz-b'), dfEl = document.getElementById('tz-df'), phiEl = document.getElementById('tz-phi');
  const cEl = document.getElementById('tz-c'), gEl = document.getElementById('tz-gamma');
  const qallResEl = document.getElementById('tz-res-qall'), fctResEl = document.getElementById('tz-res-factors');

  function update() {
    const B = parseFloat(bEl.value), D_f = parseFloat(dfEl.value), phi_deg = parseFloat(phiEl.value);
    const c = parseFloat(cEl.value), gamma = parseFloat(gEl.value);

    if (isNaN(B) || isNaN(D_f) || isNaN(phi_deg) || isNaN(c) || isNaN(gamma) || B <= 0 || D_f < 0 || phi_deg < 0 || phi_deg >= 50 || c < 0 || gamma <= 0) return;

    const phi_rad = (phi_deg * Math.PI) / 180.0;

    // Surcharge at foundation base: q = gamma * D_f
    const q_surcharge = gamma * D_f;

    // Terzaghi Bearing Capacity Factors:
    // N_q = exp( (3*pi/2 - phi)*tan(phi) ) / ( 2 * cos^2(45 + phi/2) ) approx standard formula:
    const a_angle = (0.75 * Math.PI) - (phi_rad / 2.0);
    const N_q = (Math.exp(2.0 * ((0.75 * Math.PI) - (phi_rad / 2.0)) * Math.tan(phi_rad))) / (2.0 * Math.pow(Math.cos((Math.PI / 4.0) + (phi_rad / 2.0)), 2));
    const N_c = phi_deg > 0 ? (N_q - 1.0) / Math.tan(phi_rad) : 5.7;
    const K_pg = 1.0 + (phi_deg / 10.0); // empirical passive earth pressure coefficient
    const N_gamma = 0.5 * ( (K_pg / Math.pow(Math.cos(phi_rad), 2)) - 1.0 ) * Math.tan(phi_rad);

    // Terzaghi Strip Footing Ultimate Capacity:
    // q_ult = c * N_c + q_surcharge * N_q + 0.5 * gamma * B * N_gamma
    const q_ult = (c * N_c) + (q_surcharge * N_q) + (0.5 * gamma * B * Math.max(0.1, N_gamma));

    // Allowable bearing capacity with Safety Factor FS = 3.0:
    const FS = 3.0;
    const q_all = q_ult / FS;

    qallResEl.textContent = 'Allowable q_all = ' + q_all.toFixed(1) + ' kPa (FS = 3.0)';
    fctResEl.textContent = 'Ultimate q_ult = ' + q_ult.toFixed(1) + ' kPa | N_c = ' + N_c.toFixed(1) + ', N_q = ' + N_q.toFixed(1) + ', N_γ = ' + Math.max(0, N_gamma).toFixed(1) + ' (B = ' + B + 'm, D_f = ' + D_f + 'm)';
  }

  [bEl, dfEl, phiEl, cEl, gEl].forEach(el => el.addEventListener('input', update));
  update();
})();

terzaghi-bearing-capacity-shallow-strip-.js:
(() => {
  'use strict';
  const bEl = document.getElementById('bg-b'), dfEl = document.getElementById('bg-df');
  const cEl = document.getElementById('bg-c'), phiEl = document.getElementById('bg-phi');
  const gmEl = document.getElementById('bg-gamma'), fsEl = document.getElementById('bg-fs');
  const quResEl = document.getElementById('bg-res-qult'), fcResEl = document.getElementById('bg-res-factors');

  function update() {
    const B = parseFloat(bEl.value), D_f = parseFloat(dfEl.value);
    const c = parseFloat(cEl.value), phi_deg = parseFloat(phiEl.value);
    const gamma = parseFloat(gmEl.value), FS = parseFloat(fsEl.value);

    if (isNaN(B) || isNaN(D_f) || isNaN(c) || isNaN(phi_deg) || isNaN(gamma) || isNaN(FS) || B <= 0 || D_f < 0 || phi_deg < 0 || phi_deg >= 45 || gamma <= 0 || FS <= 0) return;

    const phi_rad = (phi_deg * Math.PI) / 180.0;

    // Terzaghi / Meyerhof bearing capacity factors:
    // N_q = exp( pi * tan(phi) ) * tan^2( 45° + phi/2 )
    const N_q = Math.exp(Math.PI * Math.tan(phi_rad)) * Math.pow(Math.tan((Math.PI / 4.0) + (phi_rad / 2.0)), 2);
    // N_c = (N_q - 1) / tan(phi)  (or 5.14 for phi = 0)
    const N_c = phi_deg > 0 ? (N_q - 1.0) / Math.tan(phi_rad) : 5.14;
    // N_gamma approx 2 * (N_q + 1) * tan(phi) (Vesic / Meyerhof)
    const N_gamma = 2.0 * (N_q + 1.0) * Math.tan(phi_rad);

    // Surcharge pressure q = gamma * D_f
    const q_surcharge = gamma * D_f;

    // Terzaghi ultimate bearing capacity for strip footing:
    // q_ult = c * N_c + q * N_q + 0.5 * gamma * B * N_gamma
    const term_c = c * N_c;
    const term_q = q_surcharge * N_q;
    const term_gamma = 0.5 * gamma * B * N_gamma;

    const q_ult = term_c + term_q + term_gamma;
    const q_all = q_ult / FS;

    quResEl.textContent = 'Ultimate q_ult = ' + Math.round(q_ult).toLocaleString() + ' kPa (Allowable q_all = ' + Math.round(q_all).toLocaleString() + ' kPa)';
    fcResEl.textContent = 'Factors: N_c=' + N_c.toFixed(1) + ', N_q=' + N_q.toFixed(1) + ', N_γ=' + N_gamma.toFixed(1) + ' (Cohesion: ' + Math.round(term_c) + ', Surcharge: ' + Math.round(term_q) + ', Wedge: ' + Math.round(term_gamma) + ' kPa)';
  }

  [bEl, dfEl, cEl, phiEl, gmEl, fsEl].forEach(el => el.addEventListener('input', update));
  update();
})();

