(() => {
  'use strict';
  const mdEl = document.getElementById('tj-mdot'), veEl = document.getElementById('tj-ve');
  const v0El = document.getElementById('tj-v0'), mfEl = document.getElementById('tj-mf');
  const fnResEl = document.getElementById('tj-res-fn'), tsfcResEl = document.getElementById('tj-res-tsfc');

  function update() {
    const mdot = parseFloat(mdEl.value), v_e = parseFloat(veEl.value);
    const v_0 = parseFloat(v0El.value), mdot_f = parseFloat(mfEl.value);

    if (isNaN(mdot) || isNaN(v_e) || isNaN(v_0) || isNaN(mdot_f) || mdot <= 0 || v_e <= v_0 || mdot_f <= 0) return;

    // Net thrust F_n = mdot * (v_e - v_0)  [Newtons -> kN]
    const F_n_N = mdot * (v_e - v_0);
    const F_n_kN = F_n_N / 1000.0;
    const F_n_lbf = F_n_N * 0.224809;

    // TSFC in g / (kN * s) = (mdot_f * 1000) / F_n_kN
    const TSFC_SI = (mdot_f * 1000.0) / F_n_kN;
    const TSFC_imperial = (mdot_f * 3600.0 * 2.20462) / F_n_lbf;

    // Propulsive efficiency: eta_p = 2 * v_0 / (v_e + v_0)
    const eta_p = (2.0 * v_0) / (v_e + v_0) * 100.0;

    fnResEl.textContent = 'Net Thrust F_n = ' + F_n_kN.toFixed(2) + ' kN (' + Math.round(F_n_lbf).toLocaleString() + ' lbf)';
    tsfcResEl.textContent = 'TSFC = ' + TSFC_SI.toFixed(2) + ' g/(kN·s) (' + TSFC_imperial.toFixed(3) + ' lb/(lbf·hr)) | Propulsive η_p = ' + eta_p.toFixed(1) + '%';
  }

  [mdEl, veEl, v0El, mfEl].forEach(el => el.addEventListener('input', update));
  update();
})();

turbulence-intensity-kinetic-energy-k-om.js:
(() => {
  'use strict';
  const uEl = document.getElementById('trb-u'), iEl = document.getElementById('trb-i'), dhEl = document.getElementById('trb-dh');
  const kResEl = document.getElementById('trb-res-k'), omResEl = document.getElementById('trb-res-om');

  const C_mu = 0.09;

  function update() {
    const U = parseFloat(uEl.value), IPct = parseFloat(iEl.value), Dh = parseFloat(dhEl.value);
    if (isNaN(U) || isNaN(IPct) || isNaN(Dh) || U <= 0 || IPct <= 0 || Dh <= 0) return;

    const I = IPct / 100;

    // Turbulent kinetic energy k = 1.5 * (U * I)^2  [m^2 / s^2]
    const k = 1.5 * Math.pow(U * I, 2);

    // Turbulent length scale l approx = 0.07 * Dh  [meters]
    const l_m = 0.07 * Dh;
    const l_mm = l_m * 1000;

    // Dissipation rate epsilon = (C_mu^0.75 * k^1.5) / l  [m^2 / s^3]
    const epsilon = (Math.pow(C_mu, 0.75) * Math.pow(k, 1.5)) / l_m;

    // Specific dissipation rate omega = k^0.5 / (C_mu^0.25 * l) = epsilon / (C_mu * k)  [s^-1]
    const omega = epsilon / (C_mu * k);

    // Eddy viscosity ratio (nu_t / nu)
    const nu_t = k / omega; // m^2 / s

    kResEl.textContent = 'k = ' + k.toFixed(3) + ' m² / s² (Turbulent Energy)';
    omResEl.textContent = 'ω = ' + omega.toFixed(1) + ' s⁻¹ | ε = ' + epsilon.toFixed(2) + ' m²/s³ (Length Scale l = ' + l_mm.toFixed(1) + ' mm, ν_t = ' + (nu_t * 1e4).toFixed(1) + ' cm²/s)';
  }

  [uEl, iEl, dhEl].forEach(el => el.addEventListener('input', update));
  update();
})();

