(() => {
  'use strict';
  const inEl = document.getElementById('slug-input');
  const sepEl = document.getElementById('slug-sep');
  const stopEl = document.getElementById('slug-remove-stopwords');
  const outEl = document.getElementById('slug-output');
  const btn = document.getElementById('primary-action-btn');
  const clearBtn = document.getElementById('clear-action-btn');
  const copyBtn = document.getElementById('copy-slug-btn');
  const msgEl = document.getElementById('tool-message');
  const resCard = document.getElementById('slug-res-card');

  const STOP_WORDS = new Set(['a', 'an', 'the', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were']);

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  function generateSlug() {
    const raw = inEl.value.trim();
    if (!raw) {
      setMsg('Please enter a title or text to slugify.', true);
      resCard.style.display = 'none';
      return;
    }
    const sep = sepEl.value;
    let words = raw.toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // remove diacritics
      .replace(/[^a-z0-9\s-_]/g, '')
      .split(/[\s-_]+/);

    if (stopEl.checked) {
      words = words.filter(w => w && !STOP_WORDS.has(w));
    } else {
      words = words.filter(Boolean);
    }

    const slug = words.join(sep);
    outEl.value = slug;
    resCard.style.display = 'block';
    setMsg('Generated clean URL slug.');
  }

  btn.addEventListener('click', generateSlug);
  inEl.addEventListener('input', generateSlug);
  sepEl.addEventListener('change', generateSlug);
  stopEl.addEventListener('change', generateSlug);

  copyBtn.addEventListener('click', () => {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outEl.value);
    }
    setMsg('Slug copied to clipboard.');
  });

  clearBtn.addEventListener('click', () => {
    inEl.value = ''; outEl.value = '';
    resCard.style.display = 'none';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

url-slug-seo-generator-sanitizer.js:
(() => {
  'use strict';
  const inEl = document.getElementById('slug-in'), outEl = document.getElementById('slug-out');

  function generateSlug(str) {
    return str
      .normalize('NFD') // Normalize accented characters
      .replace(/[\u0300-\u036f]/g, '') // Remove diacritics
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9\s-]/g, '') // Remove invalid chars
      .replace(/[\s_-]+/g, '-') // Replace spaces and underscores with single hyphen
      .replace(/^-+|-+$/g, ''); // Remove leading and trailing hyphens
  }

  function update() {
    outEl.value = generateSlug(inEl.value);
  }

  inEl.addEventListener('input', update);
  update();
})();

url-to-video-player.js:
document.addEventListener('DOMContentLoaded', () => {
  const urlInput = document.getElementById('url-to-video-player-input');
  const playBtn = document.getElementById('primary-action-btn');
  const pipBtn = document.getElementById('pip-btn');
  const fullscreenBtn = document.getElementById('fullscreen-btn');
  const copyBtn = document.getElementById('copy-output');
  const clearBtn = document.getElementById('clear-text');
  const msg = document.getElementById('url-to-video-player-message');
  const video = document.getElementById('video-player');
  const placeholder = document.getElementById('placeholder-text');
  const speedButtons = document.querySelectorAll('[data-speed]');

  let hlsInstance = null;

  function loadVideo(url) {
    if (!url) {
      msg.textContent = 'Please enter a valid video URL.';
      return;
    }

    placeholder.style.display = 'none';
    video.style.display = 'block';

    if (hlsInstance) {
      hlsInstance.destroy();
      hlsInstance = null;
    }

    if (url.includes('.m3u8') && window.Hls && window.Hls.isSupported()) {
      hlsInstance = new window.Hls();
      hlsInstance.loadSource(url);
      hlsInstance.attachMedia(video);
      hlsInstance.on(window.Hls.Events.MANIFEST_PARSED, () => {
        video.play().catch(() => {});
        msg.textContent = 'Playing HLS stream.';
      });
      hlsInstance.on(window.Hls.Events.ERROR, (event, data) => {
        if (data.fatal) {
          msg.textContent = 'Error loading HLS stream. Check CORS or URL validity.';
        }
      });
    } else {
      video.src = url;
      video.load();
      video.play().then(() => {
        msg.textContent = 'Playing video stream.';
      }).catch((e) => {
        msg.textContent = 'Loaded video. Click play button on video player to start.';
      });
    }

    pipBtn.disabled = !document.pictureInPictureEnabled;
    fullscreenBtn.disabled = false;
    copyBtn.disabled = false;
  }

  playBtn?.addEventListener('click', () => {
    const url = urlInput.value.trim();
    loadVideo(url);
  });

  urlInput?.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      loadVideo(urlInput.value.trim());
    }
  });

  pipBtn?.addEventListener('click', () => {
    if (document.pictureInPictureElement) {
      document.exitPictureInPicture().catch(() => {});
    } else if (video && video.requestPictureInPicture) {
      video.requestPictureInPicture().catch((err) => {
        msg.textContent = 'Picture in Picture failed: ' + err.message;
      });
    }
  });

  fullscreenBtn?.addEventListener('click', () => {
    if (video.requestFullscreen) {
      video.requestFullscreen();
    } else if (video.webkitRequestFullscreen) {
      video.webkitRequestFullscreen();
    } else if (video.msRequestFullscreen) {
      video.msRequestFullscreen();
    }
  });

  speedButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      speedButtons.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      const speed = parseFloat(btn.getAttribute('data-speed'));
      if (video && !isNaN(speed)) {
        video.playbackRate = speed;
        msg.textContent = `Playback speed set to ${speed}x.`;
      }
    });
  });

  copyBtn?.addEventListener('click', () => {
    if (window.NikTool && window.NikTool.copy) {
      window.NikTool.copy(urlInput.value, copyBtn);
    }
  });

  clearBtn?.addEventListener('click', () => {
    if (hlsInstance) {
      hlsInstance.destroy();
      hlsInstance = null;
    }
    video.pause();
    video.removeAttribute('src');
    video.load();
    video.style.display = 'none';
    placeholder.style.display = 'block';
    urlInput.value = '';
    pipBtn.disabled = true;
    fullscreenBtn.disabled = true;
    copyBtn.disabled = true;
    msg.textContent = 'Ready. Enter video URL above.';
  });
});

