﻿(function() {
  'use strict';

  const RATE_USD_INR = 83.50;

  const usdInput = document.getElementById('usd-input');
  const inrOutput = document.getElementById('inr-output');
  const convertBtn = document.getElementById('primary-action-btn');
  const copyBtn = document.getElementById('copy-output');
  const clearBtn = document.getElementById('clear-text');
  const msgEl = document.getElementById('usd-inr-message');
  const rateInfo = document.getElementById('rate-info');
  const quickBtns = document.querySelectorAll('.quick-amount');

  function formatINR(num) {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(num);
  }

  function doConvert() {
    const val = parseFloat(usdInput.value);
    if (isNaN(val) || val < 0) {
      inrOutput.value = '';
      copyBtn.disabled = true;
      if (usdInput.value !== '') showMsg('Please enter a valid positive amount.', true);
      return;
    }
    const result = val * RATE_USD_INR;
    inrOutput.value = `$${val.toFixed(2)} USD = ${formatINR(result)}\n\nIn words: approx. ${Math.round(result).toLocaleString('en-IN')} Rupees`;
    copyBtn.disabled = false;
    showMsg(`Converted $${val.toFixed(2)} USD → ${formatINR(result)} INR`);
  }

  function showMsg(text, isError) {
    msgEl.textContent = text;
    msgEl.classList.toggle('is-error', !!isError);
  }

  usdInput.addEventListener('input', doConvert);
  convertBtn.addEventListener('click', doConvert);

  quickBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      usdInput.value = btn.getAttribute('data-amount');
      doConvert();
    });
  });

  copyBtn.addEventListener('click', function() {
    navigator.clipboard.writeText(inrOutput.value).then(function() {
      showMsg('Result copied to clipboard!');
    }).catch(function() {
      showMsg('Failed to copy.', true);
    });
  });

  clearBtn.addEventListener('click', function() {
    usdInput.value = '';
    inrOutput.value = '';
    copyBtn.disabled = true;
    showMsg('Cleared. Enter a new amount in USD.');
  });
})();

utm-grid-convergence-scale-factor-calcul.js:
(() => {
  'use strict';
  const latEl = document.getElementById('utm-lat'), lonEl = document.getElementById('utm-lon'), cmEl = document.getElementById('utm-cm');
  const gResEl = document.getElementById('utm-res-gamma'), kResEl = document.getElementById('utm-res-k');

  const k0 = 0.9996; // Standard UTM central meridian scale factor

  function update() {
    const lat = parseFloat(latEl.value), lon = parseFloat(lonEl.value), cm = parseFloat(cmEl.value);
    if (isNaN(lat) || isNaN(lon) || isNaN(cm) || lat < -80 || lat > 84) return;

    const phiRad = (lat * Math.PI) / 180;
    const dLamDeg = lon - cm;
    const dLamRad = (dLamDeg * Math.PI) / 180;

    // First-order grid convergence: gamma = dLam * sin(phi)
    const gammaDeg = dLamDeg * Math.sin(phiRad);
    const gammaArcMin = gammaDeg * 60;

    // Transverse Mercator scale factor k ≈ k0 * (1 + 0.5 * (dLam * cos phi)^2)
    const k = k0 * (1 + 0.5 * Math.pow(dLamRad * Math.cos(phiRad), 2));

    gResEl.textContent = (gammaDeg >= 0 ? '+' : '') + gammaDeg.toFixed(3) + '° (' + gammaArcMin.toFixed(1) + ' arcmin)';
    kResEl.textContent = 'k = ' + k.toFixed(5) + ' (Grid Distance / Ground Distance)';
  }

  [latEl, lonEl, cmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

uuid-v4-v7-bulk-generator.js:
(() => {
  'use strict';
  const countEl = document.getElementById('uuid-count'), verEl = document.getElementById('uuid-version');
  const caseEl = document.getElementById('uuid-case'), outEl = document.getElementById('uuid-output');
  const btn = document.getElementById('primary-action-btn'), clearBtn = document.getElementById('clear-action-btn');
  const copyBtn = document.getElementById('copy-uuid-btn'), msgEl = document.getElementById('tool-message');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  function genV4() {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
      const r = (Math.random() * 16) | 0;
      return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
    });
  }

  function genV7() {
    const now = Date.now();
    const timeHex = now.toString(16).padStart(12, '0');
    const rand = Array.from(crypto.getRandomValues(new Uint8Array(10)))
      .map(b => b.toString(16).padStart(2, '0')).join('');

    // Format: 018e47f2-xxxx-7xxx-yxxx-xxxxxxxxxxxx
    return (
      timeHex.slice(0, 8) + '-' +
      timeHex.slice(8, 12) + '-' +
      '7' + rand.slice(0, 3) + '-' +
      ((parseInt(rand.slice(3, 4), 16) & 0x3) | 0x8).toString(16) + rand.slice(4, 7) + '-' +
      rand.slice(7, 19)
    );
  }

  function generate() {
    const count = Math.min(500, Math.max(1, parseInt(countEl.value, 10) || 10));
    const ver = verEl.value;
    const isUpper = caseEl.value === 'upper';

    const list = [];
    for (let i = 0; i < count; i++) {
      let id = ver === 'v7' ? genV7() : genV4();
      list.push(isUpper ? id.toUpperCase() : id.toLowerCase());
    }

    outEl.value = list.join('\n');
    setMsg('Generated ' + count + ' ' + ver.toUpperCase() + ' UUIDs.');
  }

  btn.addEventListener('click', generate);
  verEl.addEventListener('change', generate);
  caseEl.addEventListener('change', generate);

  generate();

  copyBtn.addEventListener('click', () => {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outEl.value);
    }
    setMsg('UUIDs copied to clipboard.');
  });

  clearBtn.addEventListener('click', () => {
    outEl.value = '';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

