    const e = parseFloat(eEl.value), S = parseFloat(sEl.value);

    if (isNaN(CL) || isNaN(AR) || isNaN(e) || isNaN(S) || CL <= 0 || AR <= 0 || e <= 0 || S <= 0) return;

