(() => {
  'use strict';
  const xEl = document.getElementById('z-raw'), muEl = document.getElementById('z-mean'), sdEl = document.getElementById('z-sd');
  const btn = document.getElementById('primary-action-btn'), clearBtn = document.getElementById('clear-action-btn');
  const msgEl = document.getElementById('tool-message'), resCard = document.getElementById('z-res-card');
  const resZ = document.getElementById('z-res-val'), resPct = document.getElementById('z-res-pct'), resPval = document.getElementById('z-res-pval');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  // Approximation of cumulative standard normal distribution
  function normalCDF(z) {
    const t = 1 / (1 + 0.2316419 * Math.abs(z));
    const d = 0.3989422804014327 * Math.exp(-z * z / 2);
    const p = d * t * (0.31938153 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
    return z > 0 ? 1 - p : p;
  }

  btn.addEventListener('click', () => {
    const x = parseFloat(xEl.value), mu = parseFloat(muEl.value), sd = parseFloat(sdEl.value);
    if (isNaN(x) || isNaN(mu) || isNaN(sd) || sd <= 0) {
      setMsg('Please enter valid numerical parameters (Standard Deviation must be > 0).', true);
      resCard.style.display = 'none'; return;
    }

    const z = (x - mu) / sd;
    const cdf = normalCDF(z);
    const pct = cdf * 100;
    const rightP = 1 - cdf;

    resZ.textContent = (z >= 0 ? '+' : '') + z.toFixed(4);
    resPct.textContent = pct.toFixed(2) + '%';
    resPval.textContent = rightP.toFixed(4);

    resCard.style.display = 'block';
    setMsg('Z-score calculated successfully.');
  });

  clearBtn.addEventListener('click', () => {
    xEl.value = ''; muEl.value = ''; sdEl.value = ''; resCard.style.display = 'none';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

z-score-to-p-value-normal-cdf-calculator.js:
(() => {
  'use strict';
  const zEl = document.getElementById('zp-z');
  const twoEl = document.getElementById('zp-res-two'), oneEl = document.getElementById('zp-res-one'), cdfEl = document.getElementById('zp-res-cdf');

  // Error function approximation
  function erf(x) {
    const a1 =  0.254829592, a2 = -0.284496736, a3 =  1.421413741;
    const a4 = -1.453152027, a5 =  1.061405429, p  =  0.3275911;
    const sign = x < 0 ? -1 : 1;
    x = Math.abs(x);
    const t = 1.0 / (1.0 + p * x);
    const y = 1.0 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-x * x);
    return sign * y;
  }

  function normCDF(z) {
    return 0.5 * (1 + erf(z / Math.SQRT2));
  }

  function update() {
    const z = parseFloat(zEl.value);
    if (isNaN(z)) return;

    const cdf = normCDF(z);
    const absZ = Math.abs(z);
    const twoTail = 2 * (1 - normCDF(absZ));
    const rightTail = 1 - cdf;

    twoEl.textContent = 'p = ' + twoTail.toFixed(4);
    oneEl.textContent = 'p = ' + rightTail.toFixed(4);
    cdfEl.textContent = 'Φ(Z) = ' + cdf.toFixed(4);
  }

  zEl.addEventListener('input', update);
  update();
})();

z-transform-discrete-transfer-function-p.js:
(() => {
  'use strict';
  const b0El = document.getElementById('zt-b0'), b1El = document.getElementById('zt-b1'), a1El = document.getElementById('zt-a1');
  const stResEl = document.getElementById('zt-res-stab'), hzResEl = document.getElementById('zt-res-hz');

  function update() {
    const b0 = parseFloat(b0El.value), b1 = parseFloat(b1El.value), a1 = parseFloat(a1El.value);
    if (isNaN(b0) || isNaN(b1) || isNaN(a1)) return;

    // Pole is at z = a1
    const pole_mag = Math.abs(a1);
    // Zero is at z = -b1 / b0
    const zero = b0 !== 0 ? -b1 / b0 : 0;

    let stability = '';
    let color = '#22543d';

    if (pole_mag < 1.0) {
      stability = 'BIBO STABLE (|z_pole| = ' + pole_mag.toFixed(2) + ' < 1.00: Pole strictly inside the Unit Circle)';
      color = '#22543d';
    } else if (pole_mag === 1.0) {
      stability = 'MARGINALLY STABLE (|z_pole| = 1.00: Pole on the Unit Circle boundary -> Sustained oscillation)';
      color = '#d97706';
    } else {
      stability = 'UNSTABLE (|z_pole| = ' + pole_mag.toFixed(2) + ' > 1.00: Pole outside Unit Circle -> Exponential overflow!)';
      color = '#c53030';
    }

    stResEl.textContent = stability;
    stResEl.style.color = color;
    hzResEl.textContent = 'H(z) = (' + b0.toFixed(2) + 'z + ' + b1.toFixed(2) + ') / (z - ' + a1.toFixed(2) + ') | Zero: z = ' + zero.toFixed(2) + ' | Pole: z = ' + a1.toFixed(2);
    hzResEl.style.color = color;
  }

  [b0El, b1El, a1El].forEach(el => el.addEventListener('input', update));
  update();
})();

zener-diode-voltage-regulator-calculator.js:
(() => {
  'use strict';
  const vinEl = document.getElementById('zn-vin'), vzEl = document.getElementById('zn-vz');
  const ilEl = document.getElementById('zn-il'), izEl = document.getElementById('zn-iz');
  const rsResEl = document.getElementById('zn-res-rs'), pzResEl = document.getElementById('zn-res-pz');

  function update() {
    const vinMin = parseFloat(vinEl.value), vz = parseFloat(vzEl.value);
    const ilMa = parseFloat(ilEl.value), izMa = parseFloat(izEl.value);

    if (isNaN(vinMin) || isNaN(vz) || isNaN(ilMa) || isNaN(izMa) || vinMin <= vz || vz <= 0 || ilMa < 0 || izMa <= 0) return;

    // Total current through Rs = I_L(max) + I_z(min)
    const iTotA = (ilMa + izMa) * 1e-3;
    // R_s = (V_in(min) - V_z) / I_total (Ohms)
    const rsOhms = (vinMin - vz) / iTotA;

    // Max Zener power occurs at no-load (I_L = 0), so all current flows through Zener:
    // P_z(max) = V_z * ((V_in(min) - V_z) / R_s)
    const pzWatts = vz * ((vinMin - vz) / rsOhms);
    const pzMw = pzWatts * 1000;

    rsResEl.textContent = Math.round(rsOhms) + ' Ω';
    pzResEl.textContent = pzMw >= 1000 ? pzWatts.toFixed(2) + ' Watts' : pzMw.toFixed(1) + ' mW (' + (pzMw > 500 ? 'Use 1W Zener' : 'Use 0.5W Zener') + ')';
  }

  [vinEl, vzEl, ilEl, izEl].forEach(el => el.addEventListener('input', update));
  update();
})();
